using System;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
class StaadForceRow {public int Member,Node;public string LoadCase;public double Fx,Fy,Fz,Mx,My,Mz;}
static class StaadForces {
 static string Header(string value){return Regex.Replace((value??"").Trim().ToLowerInvariant(),@"[\s_]+","");}
 static List<string> Split(string line,char separator){var fields=new List<string>();var field=new StringBuilder();bool quoted=false;for(int i=0;i<line.Length;i++){char c=line[i];if(c=='"'){if(quoted&&i+1<line.Length&&line[i+1]=='"'){field.Append('"');i++;}else quoted=!quoted;}else if(c==separator&&!quoted){fields.Add(field.ToString().Trim());field.Length=0;}else field.Append(c);}if(quoted)throw new Exception("Unclosed quote in STAAD table.");fields.Add(field.ToString().Trim());return fields;}
 public static List<StaadForceRow> Parse(string text,string forceUnit,string momentUnit){double force=forceUnit=="kN"?1:forceUnit=="N"?.001:forceUnit=="kip"?4.4482216152605:double.NaN;double moment=momentUnit=="kN-m"?1:momentUnit=="N-mm"?.000001:momentUnit=="kip-ft"?1.3558179483314:double.NaN;if(double.IsNaN(force)||double.IsNaN(moment))throw new Exception("Select explicit STAAD force and moment units.");var lines=(text??"").Replace("\r","").Split('\n');string[] headers=null;char separator='\t';int headerRow=-1;for(int n=0;n<lines.Length;n++){char sep=lines[n].Contains("\t")?'\t':',';var fields=Split(lines[n],sep);if(fields.Any(f=>Regex.IsMatch(Header(f),@"^fx(?:$|\(|\[|kn|n$|kip)"))&&fields.Any(f=>Header(f)=="beam"||Header(f)=="member"||Header(f)=="memberid")){headers=fields.ToArray();separator=sep;headerRow=n;break;}}if(headers==null)throw new Exception("Paste/export a STAAD Beam End Forces or Envelope table INCLUDING Beam, L/C, Node and Fx/Fy/Fz/Mx/My/Mz headers.");
  Func<string,int> index=name=>Array.FindIndex(headers,h=>{string key=Header(h);return name=="member"?key=="beam"||key=="member"||key=="memberid":name=="case"?key=="l/c"||key=="loadcase"||key=="loadcaseid":name=="node"?key=="node"||key=="nodeid":Regex.IsMatch(key,"^"+name+@"(?:$|\(|\[|kn|n(?:mm)?$|kip)");});int member=index("member"),load=index("case"),node=index("node");var components=new[]{"fx","fy","fz","mx","my","mz"};int[] cols=components.Select(index).ToArray();if(load<0||node<0||cols.Any(c=>c<0))throw new Exception("Missing STAAD force/moment, load-case or node columns.");string fxHeader=Header(headers[cols[0]]),mxHeader=Header(headers[cols[3]]);if((fxHeader.Contains("kn")&&forceUnit!="kN")||(fxHeader.Contains("kip")&&forceUnit!="kip")||(mxHeader.Contains("kn")&&momentUnit!="kN-m")||(mxHeader.Contains("kip")&&momentUnit!="kip-ft"))throw new Exception("Selected units conflict with STAAD column headers.");if((fxHeader=="fxn"&&forceUnit!="N")||(mxHeader=="mxn-mm"&&momentUnit!="N-mm")||(mxHeader=="mxnmm"&&momentUnit!="N-mm"))throw new Exception("Selected units conflict with STAAD column headers.");int required=new[]{member,load,node}.Concat(cols).Max();var rows=new List<StaadForceRow>();string lastMember="",lastCase="";
  for(int n=headerRow+1;n<lines.Length;n++){if(string.IsNullOrWhiteSpace(lines[n]))continue;var fields=Split(lines[n],separator);if(fields.Count<=required)throw new Exception("Incomplete STAAD row "+(n+1)+". Copy the whole table; do not remove blank columns.");if(Header(fields[member])==Header(headers[member]))continue;string memberText=fields[member]==""?lastMember:fields[member],caseText=fields[load]==""?lastCase:fields[load];int m,nd;if(!int.TryParse(memberText,out m)||m<=0||!int.TryParse(fields[node],out nd)||nd<=0||caseText=="")throw new Exception("Invalid member/node/load case at STAAD row "+(n+1));double[] numbers=new double[6];for(int k=0;k<6;k++){if(fields[cols[k]].Contains(",")&&!Regex.IsMatch(fields[cols[k]],@"^[+-]?\d{1,3}(,\d{3})+(\.\d+)?([eE][+-]?\d+)?$"))throw new Exception("Ambiguous numeric separator at STAAD row "+(n+1)+". Use decimal points.");if(!double.TryParse(fields[cols[k]],NumberStyles.Float|NumberStyles.AllowThousands,CultureInfo.InvariantCulture,out numbers[k])||double.IsNaN(numbers[k])||double.IsInfinity(numbers[k]))throw new Exception("Invalid "+components[k]+" at STAAD row "+(n+1));}rows.Add(new StaadForceRow{Member=m,Node=nd,LoadCase=caseText,Fx=numbers[0]*force,Fy=numbers[1]*force,Fz=numbers[2]*force,Mx=numbers[3]*moment,My=numbers[4]*moment,Mz=numbers[5]*moment});lastMember=memberText;lastCase=caseText;}
  if(rows.Count==0)throw new Exception("No STAAD force rows found.");return rows;
 }
 public static List<StaadForceRow> Select(List<StaadForceRow> rows,string members){var ids=new HashSet<int>();foreach(string token in members.Split(new[]{',',';',' '},StringSplitOptions.RemoveEmptyEntries)){int id;if(!int.TryParse(token,out id)||id<=0)throw new Exception("Member IDs must be positive integers separated by commas.");ids.Add(id);}if(ids.Count==0)throw new Exception("Enter the member IDs to design; unrelated members must not be pooled automatically.");if(ids.Any(id=>!rows.Any(r=>r.Member==id)))throw new Exception("One or more selected members are absent from the imported force table.");return rows.Where(r=>ids.Contains(r.Member)).ToList();}
}
}
